			local AvatarEditor = game:GetService("AvatarEditorService")
			local TweenService = game:GetService("TweenService")
			local UIS = game:GetService("UserInputService")

			if _G.AvatarRigPromptUI then return end
			_G.AvatarRigPromptUI = true

			local player = Players.LocalPlayer
			local playerGui = player:WaitForChild("PlayerGui")

			local RigUI = Instance.new("ScreenGui")
			RigUI.Name = "AvatarRigPromptUI"
			RigUI.ResetOnSpawn = false
			RigUI.Parent = playerGui

			local MainFrame = Instance.new("Frame")
			MainFrame.Size = UDim2.new(0, 200, 0, 100)
			MainFrame.Position = UDim2.new(0.5, -100, 0, 20)
			MainFrame.BackgroundColor3 = Color3.fromRGB(25, 25, 35)
			MainFrame.Parent = RigUI

			local UIStroke = Instance.new("UIStroke")
			UIStroke.Thickness = 2
			UIStroke.Color = Color3.fromRGB(100, 200, 255)
			UIStroke.Parent = MainFrame

			local dragActive, dragStart, frameStart
			MainFrame.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					dragActive = true
					dragStart = input.Position
					frameStart = MainFrame.Position
				end
			end)

			UIS.InputChanged:Connect(function(input)
				if dragActive and input.UserInputType == Enum.UserInputType.MouseMovement then
					local delta = input.Position - dragStart
					MainFrame.Position = UDim2.new(
						frameStart.X.Scale,
						frameStart.X.Offset + delta.X,
						frameStart.Y.Scale,
						frameStart.Y.Offset + delta.Y
					)
				end
			end)

			UIS.InputEnded:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					dragActive = false
				end
			end)

			local function ExecuteRigChange()
				local char = player.Character
				if not char then return end

				local humanoid = char:FindFirstChildOfClass("Humanoid")
				if not humanoid then return end

				local desc = humanoid.HumanoidDescription:Clone()

				AvatarEditor:PromptSaveAvatar(desc, Enum.HumanoidRigType.R6)
				local result = AvatarEditor.PromptSaveAvatarCompleted:Wait()

				if result == Enum.AvatarPromptResult.Success then
					humanoid.Health = 0
					humanoid:ChangeState(Enum.HumanoidStateType.Dead)

					player.CharacterAdded:Wait()
					task.wait(1)

					local newHumanoid = player.Character:FindFirstChildOfClass("Humanoid")
					if newHumanoid then
						newHumanoid:ApplyDescription(desc)
						newHumanoid:BuildRigFromDescription(desc, Enum.HumanoidRigType.R6)
					end
				end
			end

			local R6Button = Instance.new("TextButton")
			R6Button.Text = "R6 MODE"
			R6Button.Size = UDim2.new(0.9, 0, 0.6, 0)
			R6Button.Position = UDim2.new(0.05, 0, 0.2, 0)
			R6Button.Font = Enum.Font.GothamBold
			R6Button.TextColor3 = Color3.new(1,1,1)
			R6Button.BackgroundColor3 = Color3.fromRGB(50, 150, 200)
			R6Button.Parent = MainFrame

			R6Button.MouseButton1Click:Connect(function()
				TweenService:Create(R6Button, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(20, 100, 150)}):Play()
				ExecuteRigChange()
				task.wait(0.2)
				TweenService:Create(R6Button, TweenInfo.new(0.2), {BackgroundColor3 = Color3.fromRGB(50, 150, 200)}):Play()
			end)

			local CloseButton = Instance.new("TextButton")
			CloseButton.Text = "X"
			CloseButton.Size = UDim2.new(0, 24, 0, 24)
			CloseButton.Position = UDim2.new(1, -26, 0, 2)
			CloseButton.Font = Enum.Font.GothamBold
			CloseButton.TextColor3 = Color3.new(1, 1, 1)
			CloseButton.BackgroundColor3 = Color3.fromRGB(180, 60, 60)
			CloseButton.BorderSizePixel = 0
			CloseButton.Parent = MainFrame

			CloseButton.MouseButton1Click:Connect(function()
				RigUI:Destroy()
				_G.AvatarRigPromptUI = nil
			end)
		end)

		closeBtn.MouseButton1Click:Connect(function()
			gui:Destroy()
		end)
	end)



end;
